2633: ad 00 d3                  LDA PORTA            ; Set
2636: 29 0f                     AND #$0f             ;     A = PORTA & $0f (15)  (Jack 1 Stick 0)
2638: 90 02                     BCC loc_263c         ; If (C == 1) Then      (joystick button NOT pressed)
